--region public
function MidFestivalBtnTaskBehavior:Refresh()
    self:InitData()
    self:RefreshUI()
end

function MidFestivalBtnTaskBehavior:OnClick()
    if not self._IsActive then
        GameUtils.Toast(localize("未解锁"))
        return
    end
    
    if not self._activityMidFestivalComponent:IsActive() then
        GameUtils.Toast(localize("活动已结束"))
        return
    end
    
    local moduleId = ActivityMidFestivalMgr:GetMidFestivalMainDialogId()
    local homeDojo = self._activityMidFestivalComponent:GetHomeDojo()
    local info = homeDojo.entranceConf[self.config.index]
    UIModule.OpenDialog({
        id = info.moduleId
    },{
        { id = moduleId }
    })
end
--endregion public

--region private
function MidFestivalBtnTaskBehavior:InitData()
    self._IsActive = true --self._activityMidFestivalComponent:IsActive()
    self._homeDojo = self._activityMidFestivalComponent:GetHomeDojo()
    self._AllCount = checkNumber(self._homeDojo.taskAllCount)
    self._passCount = checkNumber(self._homeDojo.taskPassCount)
    self._noRedPoint = checkNumber(self._homeDojo.taskTips) == -1
    
    local homeDojo = self._activityMidFestivalComponent:GetHomeDojo()
    local info = homeDojo.entranceConf[self.config.index]
    self.config.id = info.id
    self.config.vo = ActivityMidFestivalMgr:LoadMainEntryVoById(self.config.id)
end

function MidFestivalBtnTaskBehavior:RefreshUI()
    if not string.isEmpty(self.config.vo.name) then
        CfUtils.FillText(self.Text, self.config.vo.name)
    end

    if not string.isEmpty(self.config.vo.unlockPicture) then
        CfUtils.FillImage(self.ImgBg, self.config.vo.unlockPicture)
    end

    if not self._IsActive then
        local allChildGrayGraphics = self.controller.gameObject:EnsureComponent(typeof(UIAllChildGrayGraphics))
        if allChildGrayGraphics then
            allChildGrayGraphics:MarkGray(true)
        end
        CfUtils.FillText(self.TextTask, localize("已关闭"))
        CfUtils.SetActive(self.TextTask, true)
        return
    end

    CfUtils.FillText(self.TextTask, string.format("%d/%d", self._passCount, self._AllCount))

    CfUtils.SetActive(self.redPoint, not self._noRedPoint)
end
--endregion private

